/* ===== v4.7 — final art drop: tokyo, heliski, maldives + HQ stage art ===== */
(function(){
  var V47_ART = {"tokyo": "data:image/webp;base64,", "heliski": "data:image/webp;base64,", "maldives": "data:image/webp;base64,", "hq_0": "data:image/webp;base64,", "hq_1": "data:image/webp;base64,", "hq_2": "data:image/webp;base64,", "hq_3": "data:image/webp;base64,"};

  /* 1. catalog art for the last three vacation keys */
  try{
    if(typeof ART_IMG !== 'undefined'){
      ['tokyo','heliski','maldives'].forEach(function(k){ if(V47_ART[k]) ART_IMG[k] = V47_ART[k]; });
    }
  }catch(e){}

  /* 2. HQ stage art */
  try{
    window.HQ_IMG = {
      0: V47_ART['hq_0'], 1: V47_ART['hq_1'], 2: V47_ART['hq_2'], 3: V47_ART['hq_3']
    };
  }catch(e){}

  var HQ_NAMES = ['Coworking Space','Small Office','Full Office','Company HQ'];
  var HQ_BLURB = [
    'A shared desk and a lot of ambition. Cheap rent, no privacy, hard cap on seats.',
    'Your own door and your own whiteboard. Room to build a real team.',
    'A full floor with conference rooms and a lounge. This looks like a company now.',
    'A tower with your name on the lease. Recruiters notice, so do clients.'
  ];

  function v47HqStage(){
    try{ return Math.max(0, Math.min(3, (G.company.hqStage)|0)); }catch(e){ return 0; }
  }

  function v47HqCard(){
    var s = v47HqStage();
    var src = (window.HQ_IMG||{})[s];
    if(!src) return '';
    var cap = 8;
    try{ cap = (typeof HEADCOUNT_CAP !== 'undefined' && HEADCOUNT_CAP[s]) || 8; }catch(e){}
    var seats = 0;
    try{ seats = (G.company.employees||[]).length; }catch(e){}
    return '<div class="card v47-hqcard" data-v47hq="' + s + '">' +
      '<span class="v47-hqshot"><img class="hq-photo" src="' + src + '" alt=""></span>' +
      '<h3 style="margin:0 0 2px;">\uD83C\uDFE2 ' + HQ_NAMES[s] + '</h3>' +
      '<div class="muted" style="font-size:12px;">' + HQ_BLURB[s] + '</div>' +
      '<div class="muted" style="font-size:11.5px;margin-top:6px;">Stage ' + (s+1) + ' of 4 \u00b7 ' +
        seats + ' of ' + cap + ' base seats used</div>' +
    '</div>';
  }

  /* 3. show the HQ photo on the Expansion & Growth bucket (where upgrades happen) */
  try{
    if(typeof renderExpansionBucket === 'function'){
      var _v47exp = renderExpansionBucket;
      renderExpansionBucket = function(){
        var html = _v47exp.apply(this, arguments);
        try{ return v47HqCard() + html; }catch(e){ return html; }
      };
    }
  }catch(e){}

  /* 4. and on the facilities / workspace screen */
  try{
    if(typeof facilitiesSection === 'function'){
      var _v47fac = facilitiesSection;
      facilitiesSection = function(){
        var box = _v47fac.apply(this, arguments);
        try{
          if(box && box.querySelector && !box.querySelector('[data-v47hq]')){
            var card = document.createElement('div');
            card.innerHTML = v47HqCard();
            if(card.firstChild) box.insertBefore(card.firstChild, box.firstChild);
          }
        }catch(e){}
        return box;
      };
    }
  }catch(e){}

  /* 5. version chip */
  try{
    if(typeof renderOnboard === 'function'){
      var _v47ob = renderOnboard;
      renderOnboard = function(){ var r = _v47ob.apply(this, arguments); try{ v47Chip(); }catch(e){} return r; };
    }
    document.addEventListener('DOMContentLoaded', v47Chip);
    v47Chip();
    setTimeout(v47Chip, 0);
  }catch(e){}
  function v47Chip(){
    try{
      var el = document.querySelector('#onboard h1 .muted');
      if(el) el.textContent = el.textContent.replace(/v4\.\d+/, 'v4.7');
    }catch(e){}
  }

  window.v47Version = 'v4.7';
  window.v47HqCard = v47HqCard;
})();

/* HQ card styling: photo flush to the card edges, no black bars, no white lines */
(function(){
  var css = '.v47-hqcard{padding:0 !important;overflow:hidden;}' +
    '.v47-hqshot{display:block;position:relative;width:100%;aspect-ratio:7/4;overflow:hidden;line-height:0;}' +
    '.v47-hqshot img.hq-photo{position:absolute !important;inset:0 !important;top:0 !important;left:0 !important;width:100% !important;height:100% !important;}' +
    '.v47-hqcard > *:not(img):not(.v47-hqshot){margin-left:12px;margin-right:12px;}' +
    '.v47-hqcard > h3{margin-top:10px !important;}' +
    '.v47-hqcard > div:last-child{margin-bottom:12px;}' +
    '.v47-hqcard img.hq-photo{width:100% !important;max-width:none !important;border-radius:0 !important;' +
    'margin:0 !important;aspect-ratio:7/4 !important;height:auto !important;min-height:0 !important;max-height:none !important;' +
    'object-fit:cover;object-position:center;display:block;background:transparent;border:0;}';
  var s = document.createElement('style');
  s.appendChild(document.createTextNode(css));
  document.head.appendChild(s);
})();

/* ================= v4.7 fix — onboarding Load / Continue ================= */
/* Root cause: loading an older save could throw inside normalizeGame (e.g.
   missing g.ui / co.assets on saves written by earlier builds). v27LoadKey
   swallowed the exception in a bare try/catch, so the Continue and Load
   buttons looked completely dead. Fix = repair the save shape before
   normalizing, and never fail silently. */
(function v471SafeLoad(){
  try{
    var OBJ = function(o, k, def){ if(!o[k] || typeof o[k] !== "object") o[k] = def; return o[k]; };

    function repairCompany(co){
      if(!co || typeof co !== "object") return;
      OBJ(co, "assets", {});
      OBJ(co, "investCostBasis", {});
      OBJ(co, "pricing", {});
      OBJ(co, "companyChannel", []);
      OBJ(co, "leadershipChannel", []);
      OBJ(co, "csuiteChannel", []);
      OBJ(co, "staff", []);
      OBJ(co, "clients", []);
      OBJ(co, "history", []);
      OBJ(co, "opsLog", []);
      if(co.month == null) co.month = 1;
      if(co.year == null) co.year = 1;
    }

    window.v471RepairState = function(state){
      if(!state || typeof state !== "object") return state;
      OBJ(state, "ui", {});
      OBJ(state.ui, "queue", []);
      OBJ(state, "meta", {});
      OBJ(state, "personal", {});
      OBJ(state, "assistantChat", []);
      if(Array.isArray(state.companies)) state.companies.forEach(repairCompany);
      if(state.company && !Array.isArray(state.companies)) repairCompany(state.company);
      if(state.company && typeof state.company === "object") repairCompany(state.company);
      return state;
    };

    /* repair every state on its way into normalizeGame */
    if(typeof normalizeGame === "function"){
      var prevNorm = normalizeGame;
      normalizeGame = function(state){
        try{ window.v471RepairState(state); }catch(e){}
        return prevNorm.apply(this, arguments);
      };
      try{ window.normalizeGame = normalizeGame; }catch(e){}
    }

    /* loud, honest loading: tell the player when a save can't be read */
    window.v471LoadKey = function(key){
      var st = null;
      try{ st = (typeof loadSlot === "function") ? loadSlot(key) : JSON.parse(localStorage.getItem(key) || "null"); }
      catch(e){ st = null; }
      if(!st){
        alert("That save slot is empty or unreadable, so there was nothing to load.\n\nIf you have a save code, use \u201cPaste a save code to restore a run\u201d instead.");
        return false;
      }
      try{
        G = normalizeGame(st);
        if(typeof applyIndustryLabels === "function") applyIndustryLabels();
        var ob = document.getElementById("onboard");
        if(ob) ob.style.display = "none";
        renderAll();
        if(typeof toast === "function") toast("Game loaded.", "good");
        return true;
      }catch(err){
        try{ console.error("[v4.7] load failed", err); }catch(e){}
        var ob2 = document.getElementById("onboard");
        if(ob2) ob2.style.display = "";
        alert("This save was written by an older version and couldn't be opened.\n\n"
          + (err && err.message ? err.message : err)
          + "\n\nNothing was lost \u2014 the save is still in the list. Send this message to Jarvis and it can be repaired.");
        return false;
      }
    };

    if(typeof v27LoadKey === "function"){
      v27LoadKey = function(key){ return window.v471LoadKey(key); };
      try{ window.v27LoadKey = v27LoadKey; }catch(e){}
    }

    /* Safety net: delegated click handling so Continue / Load always respond,
       even if a later re-render replaces the buttons without rebinding. */
    document.addEventListener("click", function(ev){
      try{
        var t = ev.target && ev.target.closest
          ? ev.target.closest("[data-v27cont],[data-v27load],[data-v43cont],[data-v43load]") : null;
        if(!t) return;
        var key = t.getAttribute("data-v27cont") || t.getAttribute("data-v27load")
          || t.getAttribute("data-v43cont") || t.getAttribute("data-v43load");
        if(!key) return;
        if(t.__v471busy) return;
        t.__v471busy = true;
        setTimeout(function(){ t.__v471busy = false; }, 600);
        ev.preventDefault();
        ev.stopPropagation();
        window.v471LoadKey(key);
      }catch(e){}
    }, true);
  }catch(e){}
})();
